window.RZ_DB_PATCH = function (DB) {
  var D = window.RZ_DB_EN; if (!D) return;
  var I = D.I, N = D.N, S = D.S, cz2en = {};
  var tr = function (s) { return s && S[s] ? S[s] : s; };
  function en(id, cz) {
    var e = (I[id] && I[id][0]) || (cz && N[cz]) || null;
    if (e && cz && !cz2en[cz]) cz2en[cz] = e;
    return e || cz;
  }
  Object.keys(DB.names).forEach(function (id) { DB.names[id] = en(id, DB.names[id]); });
  DB.items.forEach(function (i) {
    i.name = en(i.id, i.name);
    if (i.desc) { var d = I[i.id] && I[i.id][1]; if (d) i.desc = d; else if (D.DS[i.desc]) i.desc = D.DS[i.desc]; }
  });
  DB.recipes.forEach(function (r) { en(r.id, r.name); r.parts.forEach(function (p) { en(p[0], p[1]); }); });
  DB.recipes.forEach(function (r) {
    r.name = cz2en[r.name] || en(r.id, r.name);
    r.parts.forEach(function (p) { p[1] = cz2en[p[1]] || en(p[0], p[1]); });
    if (r.rec) r.rec = cz2en[r.rec] || N[r.rec] || r.rec;
    r.toolname = tr(r.toolname);
  });
  DB.items.forEach(function (i) {
    if (i.helm) i.helm = cz2en[i.helm] || i.helm;
    if (i.cal) i.cal = cz2en[i.cal] || tr(i.cal);
    if (i.det && i.det.att) i.det.att.forEach(function (a) { if (Array.isArray(a)) a[1] = tr(a[1]); });
    ['eff', 'stops', 'sila', 'cls', 'modes'].forEach(function (k) { if (typeof i[k] === 'string') i[k] = tr(i[k]); });
    if (i.fx) i.fx.forEach(function (f) { f[0] = tr(f[0]); f[1] = String(f[1]).replace(/^ozařuje /, 'emits ').replace(/^odvádí /, 'removes '); });
    if (i.brd && i.brd.who) i.brd.who.forEach(function (w) { w[0] = tr(w[0]); });
  });
  DB.tabs.forEach(function (t) { t[1] = tr(t[1]); });
  Object.keys(DB.tools).forEach(function (k) { DB.tools[k] = tr(DB.tools[k]); });
  DB.traders.forEach(function (t) {
    t.name = tr(t.name); t.where = tr(t.where); t.fac = tr(t.fac);
    t.tiers = t.tiers.map(function (x) { return x === 'od začátku' ? 'from the start' : String(x).replace(/^pověst /, 'reputation '); });
  });
  DB.breeders.forEach(function (b) { b.name = tr(b.name); });
  DB.loadouts.forEach(function (l) { l.name = tr(l.name); l.ranks.forEach(function (r) { r.name = tr(r.name); }); });
};
